draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms and legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 30, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 - 20, H/2 + 110);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80);
  ctx.lineTo(W/2 + 20, H/2 + 110);
  ctx.stroke();

  // draw omega-3 fish
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.sin(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.stroke();

  // draw turmeric
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.cos(t), H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.stroke();

  // draw healing lines
  ctx.strokeStyle = 'green';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 100 + 50 * Math.sin(t), H/2 - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 100 + 50 * Math.cos(t), H/2 - 50);
  ctx.stroke();

  ctx.restore();
}
